void reliable_handler(int sig, siginfo_t *info, void *ucontext) {
    if (sig == SIGTERM) { /* Use only async-safe functions */ }
}

struct sigaction sa;
sigemptyset(&sa.sa_mask);

// SA_SIGINFO requires sa_sigaction handler type
sa.sa_sigaction = reliable_handler;

// SA_RESTART attempts to restart interrupted syscalls
// SA_NOCLDSTOP prevents signals when child stops/continues
sa.sa_flags = SA_RESTART | SA_SIGINFO;

// Install the reliable signal handler
sigaction(SIGTERM, &sa, NULL);


sigset_t block_set;
sigset_t old_set;

// 1. Initialize the mask
sigemptyset(&block_set);
sigaddset(&block_set, SIGINT);
sigaddset(&block_set, SIGQUIT);

// 2. Block signals (Critical Section START)
// SIG_BLOCK adds signals in 'block_set' to the current mask
sigprocmask(SIG_BLOCK, &block_set, &old_set);

/* Access global/shared resources safely here */

// 3. Unblock signals (Critical Section END)
// SIG_SETMASK restores the previous mask ('old_set')
sigprocmask(SIG_SETMASK, &old_set, NULL);
